import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.oeh4wjV1.js";const f=JSON.parse('{"title":"Horde","description":"","frontmatter":{},"headers":[],"relativePath":"formats/horde/index.md","filePath":"formats/horde/index.md","lastUpdated":1792425987000}'),o={name:"formats/horde/index.md"};function s(d,e,n,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="horde" tabindex="-1">Horde <a class="header-anchor" href="#horde" aria-label="Permalink to &quot;Horde&quot;">​</a></h1><p><a href="./../">All formats</a></p><p>Horde is a family of cooperative formats in which players face an automated enemy deck. Its versions use different life totals, wave rules, targeting decisions, and victory conditions. Pick one rules page before preparing a game.</p><table tabindex="0"><thead><tr><th>Ruleset</th><th>Setup and main differences</th></tr></thead><tbody><tr><td><a href="./variants/classic.html">Classic Zombie Horde</a></td><td>Original 2011 rules: 20 shared life per survivor, a 45–100-card Horde, three setup turns, random choices.</td></tr><tr><td><a href="./variants/open-source.html">Open Source version</a></td><td>The 2011 follow-up: reduced setup time for larger groups, a planeswalker attack procedure, and its historical ban list.</td></tr><tr><td><a href="./variants/hordemagic.html">HordeMagic.com</a></td><td>Approximately 300 cards, rarity-based waves, 100/85/70/55 shared life, and best-interest decisions.</td></tr><tr><td><a href="./variants/wiki.html">Archived wiki version</a></td><td>The repository&#39;s wiki rules snapshot, including its hand/graveyard handling, victory conditions, and difficulty options.</td></tr><tr><td><a href="./variants/raid.html">Raid</a></td><td>Ordered scenario stages and survivor loot; survivors cannot attack the Horde. The original scenario framework leaves some decisions to the designer.</td></tr></tbody></table><h2 id="boxed-set-possibilities" tabindex="-1">Boxed-set possibilities <a class="header-anchor" href="#boxed-set-possibilities" aria-label="Permalink to &quot;Boxed-set possibilities&quot;">​</a></h2><p>A Horde box can supply an enemy deck, fixed survivor decks, tokens, counters, a player-count difficulty chart, and targeting reminders. A Raid box also needs stage ordering, loot allocation, and its exact scenario victory rules.</p><p>Record each box&#39;s changes against the named version. Do not automatically apply HordeMagic.com&#39;s decisions or its life totals to a Classic Horde box.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p>The <a href="./../../sources/#horde">Horde source index</a> links the original articles and archived notes.</p>',9)])])}const u=a(o,[["render",s]]);export{f as __pageData,u as default};
